// Prueba de humo: carga la ruta 3D de la Alhambra, verifica render y captura pantallas.
import { chromium } from 'playwright';

const FILE = process.argv[2] || '/var/tmp/bench/ws-bC1Yn547/alhambra-ruta-3d.html';
const OUT = '/tmp/opencode';

const browser = await chromium.launch({
  executablePath: '/usr/bin/google-chrome',
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader']
});
const page = await browser.newPage({ viewport: { width: 1440, height: 860 } });

const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));

await page.goto('file://' + FILE);
await page.waitForTimeout(9000); // módulos + primer render
await page.screenshot({ path: OUT + '/a-intro.png' });

// iniciar ruta guiada
await page.click('#btnStart');
await page.waitForTimeout(8000);
await page.screenshot({ path: OUT + '/b-parada1.png' });

// saltar a varias paradas y comprobar texto del panel
for (const [i, name] of [[4, 'Patio de los Arrayanes'], [6, 'Patio de los Leones'], [8, 'Generalife']]) {
  await page.evaluate(idx => {
    document.querySelectorAll('#stops li')[idx].click();
  }, i);
  await page.waitForTimeout(7000);
  const cardName = await page.textContent('#stopName');
  console.log('Parada ' + (i + 1) + ' → panel dice: "' + cardName + '"');
  if (!cardName.includes(name)) errors.push('Nombre de parada incorrecto: ' + cardName);
}
await page.screenshot({ path: OUT + '/c-generalife.png' });

// vista aérea + pixel check del canvas (no negro)
await page.click('#btnOverview');
await page.waitForTimeout(8000);
await page.screenshot({ path: OUT + '/d-aerea.png' });
const px = await page.evaluate(() => {
  const c = document.querySelector('canvas');
  const g = document.createElement('canvas'); g.width = g.height = 1;
  const ctx = g.getContext('2d');
  ctx.drawImage(c, 700, 400, 1, 1, 0, 0, 1, 1);
  return ctx.getImageData(0, 0, 1, 1).data;
});
console.log('Pixel central del canvas RGBA:', px.join(','));
if (px[0] === 0 && px[1] === 0 && px[2] === 0) errors.push('El canvas renderiza en negro');

// FPS aproximado
const fps = await page.evaluate(() => new Promise(res => {
  let n = 0; const t0 = performance.now();
  const loop = () => { n++; if (performance.now() - t0 < 2000) requestAnimationFrame(loop); else res(n / 2); };
  requestAnimationFrame(loop);
}));
console.log('FPS aprox:', fps);

console.log(errors.length ? 'ERRORES:\n' + errors.join('\n---\n') : 'SIN ERRORES DE CONSOLA');
await browser.close();

// Analiza los pantallazos: brillo medio y color dominante por zonas.
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const shots = ['a-intro', 'b-parada1', 'c-generalife', 'd-aerea'];
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox'] });
const page = await browser.newPage();
await page.goto('about:blank');

for (const name of shots) {
  const stats = await page.evaluate(async (path) => {
    const img = new Image();
    img.src = 'file://' + path;
    await new Promise((ok, ko) => { img.onload = ok; img.onerror = ko; });
    const w = img.width, h = img.height;
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const zone = (x0, y0, x1, y1) => {
      const d = ctx.getImageData(x0, y0, x1 - x0, y1 - y0).data;
      let r = 0, g = 0, b = 0, dark = 0, n = 0;
      for (let i = 0; i < d.length; i += 4) {
        r += d[i]; g += d[i + 1]; b += d[i + 2]; n++;
        if (d[i] + d[i + 1] + d[i + 2] < 45) dark++;
      }
      return { rgb: [Math.round(r / n), Math.round(g / n), Math.round(b / n)], dark: +(100 * dark / n).toFixed(1) };
    };
    return {
      total: zone(0, 0, w, h),
      cielo: zone(0, 0, w, Math.round(h * 0.2)),
      centro: zone(Math.round(w * 0.3), Math.round(h * 0.4), Math.round(w * 0.7), Math.round(h * 0.8))
    };
  }, '/tmp/opencode/' + name + '.png');
  console.log(name.padEnd(12),
    'global rgb', stats.total.rgb.join(','), '| oscuros', stats.total.dark + '%',
    '| cielo', stats.cielo.rgb.join(','),
    '| centro', stats.centro.rgb.join(','));
}
await browser.close();

