import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox', '--allow-file-access-from-files'] });
const page = await browser.newPage();
await page.goto('file:///tmp/opencode/');
for (const name of ['b-parada1', 'c-generalife']) {
  const s = await page.evaluate(async (path) => {
    const img = new Image(); img.src = 'file://' + path;
    await new Promise((ok, ko) => { img.onload = ok; img.onerror = ko; });
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
    const ctx = c.getContext('2d'); ctx.drawImage(img, 0, 0);
    const avg = (x0, y0, x1, y1) => {
      const d = ctx.getImageData(x0, y0, x1 - x0, y1 - y0).data;
      let r = 0, g = 0, b = 0, n = 0;
      for (let i = 0; i < d.length; i += 4) { r += d[i]; g += d[i + 1]; b += d[i + 2]; n++; }
      return [Math.round(r / n), Math.round(g / n), Math.round(b / n)];
    };
    return {
      cielo_puro: avg(Math.round(img.width * .42), 8, Math.round(img.width * .58), 60),
      arriba: avg(Math.round(img.width * .42), 0, Math.round(img.width * .58), 30),
      medio: avg(Math.round(img.width * .45), Math.round(img.height * .45), Math.round(img.width * .55), Math.round(img.height * .55))
    };
  }, '/tmp/opencode/' + name + '.png');
  console.log(name, '| cielo', s.cielo_puro.join(','), '| arriba', s.arriba.join(','), '| centro', s.medio.join(','));
}
await browser.close();
